```python
import os, glob, json, datetime

# Common locations where uploads land
candidates = []
for root in [".", "/content", "/mnt/data", "/tmp", os.path.expanduser("~")]:
    if os.path.isdir(root):
        print(f"=== {root} ===")
        try:
            for entry in sorted(os.listdir(root)):
                full = os.path.join(root, entry)
                kind = "DIR " if os.path.isdir(full) else "FILE"
                try:
                    size = os.path.getsize(full) if os.path.isfile(full) else ""
                except Exception as e:
                    size = f"err:{e}"
                print(f"  [{kind}] {entry}  {size}")
        except Exception as e:
            print(f"  (cannot list: {e})")
        print()
    else:
        print(f"=== {root} === (does not exist)\n")
```

```python
# Hunt for spreadsheet-like files anywhere reachable
patterns = ["*.xlsx", "*.xls", "*.xlsm", "*.csv", "*.tsv", "*.ods", "*.parquet", "*.json"]
found = {}
for root in [".", "/content", "/mnt", "/tmp", os.path.expanduser("~")]:
    for p in patterns:
        for path in glob.glob(os.path.join(root, "**", p), recursive=True):
            try:
                found[path] = os.path.getsize(path)
            except Exception:
                found[path] = -1

print(f"Spreadsheet/data-like files found: {len(found)}")
for path, size in sorted(found.items()):
    print(f"  {path}  ({size} bytes)")
```

